// The registry: the instance's apps.yaml (agent-created apps; apps-mcp commits here) plus config/apps.modules.yaml
// (apps of enabled modules, generated by scripts/compile.ts, read-only). The only source of desired state; re-read on
// every use, so a git pull or an apply takes effect at once.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { parseDocument } from "yaml";
import { z } from "zod";
import { parseRoute, plainPath } from "./api.js";

/** A preview's name (previews.ts): reserved, so no registry app can share its project, secrets, checkout or database role. */
export const PREVIEW_NAME = /-pr-\d+$/;
/** Host ports for previews (loopback for the gate, the apps' tailnet node's ports): no registry app may take one. */
export const PREVIEW_PORTS = { min: 39100, max: 39399 } as const;

/** The board's own nav labels (services/board/web/src/App.tsx TABS and the phone tabs): a pin can't pose as one. */
const BOARD_TABS = ["chat", "approvals", "agents", "apps", "tasks", "activity", "costs", "brief", "settings"];

const plainRel = (p: string) => !p.startsWith("/") && !p.startsWith("~") && !p.includes("$") && !p.split(/[\\/]/).includes("..");

const PREFIX = /^\/[A-Za-z0-9._~\/-]*$/;
/** A caller's `api.paths` entry: a bare prefix, or one exact route (`POST /api/x/{id}/y`; api.ts's parseRoute rejects
 * everything else). In a flow sequence the route's space makes it ambiguous YAML (`Missing , or : between flow sequence
 * items`), so quote it: `paths: ["GET /api/x", "POST /api/x/{id}/y"]`, or use block style. */
const callerPath = z.string().refine((p) => PREFIX.test(p) || !!parseRoute(p), "paths are plain absolute path prefixes, or one exact route as 'METHOD /path' with {name} for one segment");
/** A member path is matched by requests, so it takes exactly plainPath's rules (no //, . or .., or escapes) and no query. */
const memberPath = z.string().refine((p) => {
  if (p.includes("?")) return false;
  try {
    return plainPath(p) === p;
  } catch {
    return false;
  }
}, "paths are plain absolute path prefixes, without a query string");

// `paperclip` and `sources` name AidenHQ networks in connects; `<app>-pr-<n>` names a pull request's preview (previews.ts).
const name = z.string().regex(/^[a-z][a-z0-9-]{1,30}$/).refine((n) => n !== "paperclip" && n !== "sources", "reserved name").refine((n) => !PREVIEW_NAME.test(n), "names ending -pr-<number> are previews'");
const AppSchema = z
  .object({
    name,
    repo: z.string().regex(/^[\w.-]+\/[\w.-]+$/),
    branch: z.string().default("main"),
    path: z.string().default(".").refine(plainRel, "path must be relative, without ..").refine((p) => !/\.ya?ml$/i.test(p.split(/[\\/]/).filter(Boolean).pop() ?? ""), "path is the folder in the repo that holds compose.yaml ('.' for the repo root), not the file; set compose for a different file name"),
    compose: z.string().default("compose.yaml").refine(plainRel, "compose must be relative, without .."),
    host: z.string().default("local"),
    owner: z.string(),
    // The agent people's feedback in a shared app wakes (its "App feedback: <app>" routine; default: owner). scripts/modules.ts.
    feedback_to: z.string().regex(/^[a-z0-9][a-z0-9-]{0,62}$/).optional(),
    description: z.string(),
    port: z.number().int().min(1024).max(65535).refine((p) => p < PREVIEW_PORTS.min || p > PREVIEW_PORTS.max, `ports ${PREVIEW_PORTS.min}-${PREVIEW_PORTS.max} are the previews'`).optional(),
    expose: z.boolean().default(true), // tailscale serve --https=<port>; false for non-HTTP apps (databases)
    health: z.object({ url: z.string().optional(), grace_sec: z.number().default(60) }).default({ grace_sec: 60 }),
    stateful: z.boolean().default(false),
    untrusted: z.boolean().default(false),
    internet: z.boolean().default(true),
    connects: z.array(z.string()).default([]),
    caps: z.array(z.string()).default([]),
    limits: z.object({ memory: z.string(), cpus: z.number(), pids: z.number() }).optional(),
    access: z.object({ roles: z.array(z.string()) }).optional(),
    auto_deploy: z.boolean().optional(),
    secrets: z.array(z.string().regex(/^[A-Z][A-Z0-9_]*$/, "secret names are env-style (A-Z, 0-9, _)").refine((k) => !k.startsWith("AIDENHQ_"), "AIDENHQ_* names are the platform's")).default([]), // files in the vault: <app>/<KEY>
    sources: z.array(z.string()).default([]),
    // An agent's narrow write path into the app's own API (app_api, api.ts): only these agent keys, only under these path
    // prefixes; apps-mcp signs each call's X-AidenHQ-Identity (identity.ts; docs/design/app-identity.md).
    api: z.object({
      token: z.never({ error: "api.token is gone: app_api signs each call's identity (docs/design/app-identity.md); remove it and its secret" }).optional(),
      // A caller is an agent key (the app's paths) or {agent, paths}: that agent only under its own narrower prefixes, or only
      // the exact routes it names. The app's own paths stay prefixes: where its agent API lives, not which routes it serves.
      callers: z.array(z.union([z.string().min(1), z.object({ agent: z.string().min(1), paths: z.array(callerPath).min(1) }).strict()])).min(1),
      paths: z.array(z.string().regex(PREFIX, "paths are plain absolute path prefixes")).min(1),
      // Public routes an object-form caller may reach as member even when they are outside api.paths. Off by default: admin
      // is still held to api.paths, and the caller's own paths still narrow this grant.
      member_paths: z.array(memberPath).default([]),
    }).strict().optional(),
    // Shared access (docs/design/access.md): people (not agents) who reach the app through
    // Cloudflare Access and the gate at https://<host>. Instance apps.yaml only (compile refuses it on module apps), sensitive.
    // host set: a public route through the gate and no tailscale serve route; aud: the app's own Access application tag.
    share: z.object({
      host: z.string().regex(/^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/, "host is a lowercase DNS name").optional(),
      aud: z.string().regex(/^[A-Za-z0-9_:-]{8,128}$/, "aud is the host's audience: an Access application tag, or a front door's (service:<id>)").optional(),
      // A new app's default role for people (else its manifest's, else blocked); the app's admins can change it.
      default_role: z.string().regex(/^[a-z][a-z0-9-]{1,30}$/).refine((r) => r !== "admin", "the default role is never admin").optional(),
      viewers: z.never({ error: "share.viewers is gone: app admins are named on the board and set roles on the app's Access page" }).optional(),
      admins: z.never({ error: "share.admins is gone: app admins are named on the board (Accounts, App admins)" }).optional(),
      groups: z.array(z.string()).max(0, "share.groups come in phase 2").default([]),
    }).strict().optional(),
    // Pinned into the board's nav under this label (a link to the app's own URL: the board never frames an app). Instance
    // apps.yaml only (compile refuses it on module apps) and sensitive: it adds to the owner's own surface.
    panel: z.string().regex(/^[A-Za-z0-9][A-Za-z0-9 .&-]{0,23}$/, "a panel label is 1-24 letters, digits, spaces, . & -").refine((l) => !BOARD_TABS.includes(l.toLowerCase()), "a panel label can't be one of the board's own tabs").optional(),
    database: z.literal("warehouse").optional(), // a login + schema app_<name> on the warehouse, provisioned on deploy (database.ts)
    module: z.string().optional(), // set by the compiler on module apps
    pin: z.string().regex(/^[0-9a-f]{40}$/).optional(), // module apps: the product commit the instance pins (deploys use it, not branch head)
  })
  .strict()
  .refine((a) => !a.api || a.health.url, "api needs health.url (its origin is where app_api sends requests)")
  // aud is required by compile (scripts/edge.ts) unless settings.app_login is password, which this registry doesn't know.
  .refine((a) => !a.share?.host || a.port, "share.host needs a port (the gate proxies to 127.0.0.1:<port>)")
  .refine((a) => a.internet || !a.port, "internet: false apps can't publish a port (Docker doesn't publish from internal networks)")
  .transform((a) => ({
    ...a,
    auto_deploy: a.auto_deploy ?? !a.stateful,
    // database: the app gets /run/secrets/DATABASE_URL and the warehouse network
    ...(a.database ? { connects: [...new Set([...a.connects, a.database])] } : {}),
    // Every app also gets the identity keys (AIDENHQ_IDENTITY_KEYS) and AIDENHQ_APP from the platform (policy.ts withSecrets).
    secrets: [...new Set([...a.secrets, ...(a.database ? ["DATABASE_URL"] : [])])],
  }));
export const parseApp = (raw: unknown): App => AppSchema.parse(raw);
/** `preview`: set only on a pull request's preview (previews.ts previewApp), never by the registry. */
export type App = z.output<typeof AppSchema> & { preview?: Preview };
export interface Preview { of: string; pr: number; published: number } // published: the parent's port, which its compose publishes
/**
 * The app is not expected to serve HTTP at all: not exposed on the tailnet or through the gate, not shared, no `health.url`
 * and no agent `api` (the registry needs a health.url for an api). A database is the shape this is for: it speaks its own
 * protocol, so its ports answer silence to an HTTP request. Such an app's unprobed ports are recorded as non-hard findings
 * instead of failing the deploy; a port that does answer HTTP is still judged, on this app as on any other (identityPorts).
 */
export const noHttpSurface = (app: App) => !app.expose && !app.share?.host && !app.health.url && !app.api;

const readApps = (path: string): App[] =>
  (((parseDocument(readFileSync(path, "utf8")).toJS() ?? {}) as { apps?: unknown[] }).apps ?? []).map((a) => AppSchema.parse(a));

/** The instance registry plus the module apps (absent before the first compile). */
export function loadRegistry(path: string, modulesPath?: string): App[] {
  const own = readApps(path);
  // A module app's source is the product checkout at its pin (git.ts fetchAll): only the compiler's registry may say so.
  const forged = own.find((a) => a.module || a.pin);
  if (forged) throw new Error(`${forged.name}: module and pin are set by the compiler on module apps, never in apps.yaml`);
  const apps = [...own, ...(modulesPath && existsSync(modulesPath) ? readApps(modulesPath) : [])];
  const dup = apps.find((a, i) => apps.findIndex((b) => b.name === a.name) !== i);
  if (dup) throw new Error(`duplicate app ${dup.name} in registry`);
  checkConnects(apps);
  return apps;
}

/** No app may join a shared app's network: the gate is its only caller. */
export function checkConnects(apps: App[]): void {
  for (const a of apps) {
    const t = a.connects.find((c) => apps.find((b) => b.name === c)?.share?.host);
    if (t) throw new Error(`${a.name} connects to ${t}, a shared app: shared apps are reached only through the gate`);
  }
}

/** Sets access, share, panel, stateful, untrusted, caps or database, is or connects to the warehouse, or connects to paperclip, sources, a restricted app or a shared one: only the owner's "apply" adds these. */
export function isSensitive(app: App, all: App[]): boolean {
  return app.name === "warehouse" || !!app.access || !!app.share || !!app.panel || !!app.database || app.stateful || app.untrusted || app.caps.length > 0 || app.connects.some((c) => { const t = all.find((a) => a.name === c); return c === "paperclip" || c === "sources" || c === "warehouse" || t?.access || t?.share; });
}

/** Module apps come and go with their module, never through app_remove. */
export function checkRemovable(app: App): void {
  if (app.module) throw new Error(`${app.name} comes from module ${app.module}; disable the module instead`);
}

/** Edits keep the file's comments. */
function edit(path: string, fn: (apps: import("yaml").YAMLSeq) => void): void {
  const doc = parseDocument(readFileSync(path, "utf8"));
  fn(doc.get("apps", true) as import("yaml").YAMLSeq);
  writeFileSync(path, doc.toString());
}
export const appendApp = (path: string, entry: Record<string, unknown>): void => edit(path, (apps) => void apps.add(entry));
export const removeApp = (path: string, appName: string): void =>
  edit(path, (apps) => {
    const i = apps.items.findIndex((x) => (x as any).get("name") === appName);
    if (i < 0) throw new Error(`app ${appName} is not in the registry`);
    apps.items.splice(i, 1);
  });
